import {jsPDF} from 'jspdf';
import {createIcons,icons} from 'lucide';
import {chapters,modules,glossary,shopItems,competencies,sources,regularQuestions,testQuestions,questionById,xpFor,judge,defaultProgress} from './content.js';
import './style.css';
const root=document.getElementById('app');
let taskAnchor=null;
const setTaskAnchor=el=>{const task=el?.closest?.('[data-task-id]');if(task)taskAnchor=task.dataset.taskId;};
const GUEST_KEY='rechtsklar_guest_v2';
const safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rich=x=>safe(x).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');
const icon=(n,cls='')=>`<i data-lucide="${n}" class="${cls}"></i>`;
const amt=n=>Number(n||0).toLocaleString('de-DE');
const date=n=>new Date(n||Date.now()).toLocaleDateString('de-DE');
const toArray=x=>Array.isArray(x)?x:[];
const findMod=id=>modules.find(m=>m.id===id)||modules[0];
const getItems=id=>regularQuestions.filter(q=>q.module===id);
const renderIcon=()=>{try{createIcons({icons,attrs:{'stroke-width':1.9,size:19}})}catch(e){console.warn(e)}};
let g;
try{g=JSON.parse(localStorage.getItem(GUEST_KEY)||'null')}catch{}
const state={page:'home',module:'w1',question:null,account:null,progress:g&&typeof g==='object'?{...defaultProgress(),...g}:defaultProgress(),drafts:{},notes:{},mode:'login',tab:'student',busy:false,notice:'',modal:null,solutionShown:{},reviewReady:{},teacherRows:[],leaderboard:[],teacherSelected:null,teacherPassword:null,shopFilter:'all',glossarySearch:'',diagram:{},mobileMenu:false,showGuestMerge:false};
const owned=()=>new Set(state.progress.owned||[]);
const balance=()=>Math.max(0,(state.progress.earned||0)-(state.progress.spent||0));
const level=()=>Math.floor(Math.sqrt((state.progress.earned||0)/110))+1;
const doneCount=qs=>qs.filter(q=>state.progress.answers?.[q.id]?.correct).length;
const totalDone=()=>doneCount(regularQuestions);
const saveGuest=()=>{if(!state.account){try{localStorage.setItem(GUEST_KEY,JSON.stringify(state.progress))}catch{}}};
const getAns=q=>state.progress.answers?.[q.id];
const draft=q=>state.drafts[q.id]!==undefined?state.drafts[q.id]:(getAns(q)?.answer!==undefined?structuredClone(getAns(q).answer):q.type==='classify'?q.items.map(()=>-1):q.type==='order'?q.items.map((_,i)=>(i+1)%q.items.length):q.type==='multi'?[]:q.type==='truefalse'?null:'');
function setDraft(id,value){state.drafts[id]=value;}
function note(text,bad=false){state.notice={text,bad};render();setTimeout(()=>{if(state.notice?.text===text){state.notice='';render();}},3500)}
function route(page,module,q){state.page=page||'home';if(module)state.module=module;if(q)state.question=q;state.notice='';window.scrollTo({top:0,behavior:'instant'});render()}
function progressBar(done,total){return `<div class="progress-track"><div class="progress-fill" style="width:${total?100*done/total:0}%"></div></div>`}
function avatarGraphic(size='medium'){
 const eq=state.progress.equipped||{};
 const clothes=eq.outfit||'starter';const pet=eq.pet||'none';const back=eq.back||'mint';
 const color={starter:'#9aa8ff',hoodie:'#52dfb3',blazer:'#416fbc',cosmic:'#da83fa'}[clothes]||'#9aa8ff';
 const animal={cat:'🐈',dog:'🐕',owl:'🦉'}[pet]||'';
 return `<div class="avatar-scene avatar-${size} bg-${safe(back)}" aria-label="Ihr Avatar ${safe(clothes)} mit Begleiter ${safe(pet)}"><svg viewBox="0 0 175 190" role="img" aria-label="Illustration Ihres Avatars"><ellipse cx="88" cy="178" rx="55" ry="8" fill="#0b1635" opacity=".14"/><path d="M53 172v-19q2-19 21-28h26q23 11 24 30v17" fill="${color}" stroke="#253250" stroke-width="4"/><path d="M67 131v25M106 131v25" stroke="#fff" opacity=".35" stroke-width="3"/><path d="M70 171v-15M105 171v-15" stroke="#263656" stroke-width="13" stroke-linecap="round"/><path d="M76 116v16q13 12 24 0v-16" fill="#c98d6d"/><ellipse cx="88" cy="80" rx="37" ry="43" fill="#e6ad8e"/><path d="M52 80q-13-45 20-50 27-13 46 12 13 15 5 38-4-25-18-23-20 7-43-3-6 11-10 26" fill="#27304b"/><circle cx="73" cy="85" r="2.7" fill="#26324a"/><circle cx="101" cy="85" r="2.7" fill="#26324a"/><path d="M79 99q9 8 19 0" stroke="#9a5c4c" stroke-width="2.7" fill="none" stroke-linecap="round"/><path d="M59 55q8-25 36-24" stroke="#434966" stroke-width="7" stroke-linecap="round"/><path d="M64 147l-5 18M112 147l5 18" stroke="#e6ad8e" stroke-width="11" stroke-linecap="round"/></svg>${animal?`<span class="avatar-pet">${animal}</span>`:''}<div class="avatar-shimmer">✧</div></div>`;
}
function badgeList(){const arr=[
 ['Erster Erfolg','star',totalDone()>=1],['10 Fälle gelöst','shield-check',totalDone()>=10],['Formprofi','stamp',doneCount(getItems('f3'))>=5],['50 Fälle gelöst','trophy',totalDone()>=50],['Kompetenztest','graduation-cap',doneCount(testQuestions)===testQuestions.length]
 ];return arr.map(([name,ic,has])=>`<div class="achievement ${has?'got':'locked'}">${icon(ic)}<span>${name}</span></div>`).join('')}
function navLink(page,name,ic){return `<button class="nav-link ${state.page===page?'active':''}" data-nav="${page}">${icon(ic)}<span>${name}</span></button>`}
function header(){return `<header class="topbar"><div class="top-inner"><button class="brand" data-nav="home"><span class="brand-emblem">${icon('scale')}</span><span>RECHTS<span class="brand-light">KLAR</span><small>INTERAKTIVE LERNWELT</small></span></button><nav class="main-nav" aria-label="Hauptmenü">${navLink('home','Übersicht','layout-dashboard')}${navLink('module','Kurs','book-open')}${navLink('shop','Avatar-Welt','sparkles')}${navLink('test','Abschlusstest','clipboard-check')}${navLink('checklist','Selbstcheck','list-checks')}${navLink('glossary','Glossar','library-big')}${state.account?.role==='teacher'?navLink('teacher','Lehrerbereich','users-round'):''}</nav><div class="header-right"><div class="xp-pill" title="Verfügbare XP">${icon('zap')} ${amt(balance())} <span>XP</span></div><button class="mini-avatar" data-nav="shop" aria-label="Avatar-Galerie">${avatarGraphic('tiny')}</button>${state.account?`<button class="account-button" data-nav="profile">${icon('user-round')}<span>${safe(state.account.nick)}</span></button>`:`<button class="account-button sign-in" data-action="auth-modal">${icon('log-in')}<span>Anmelden</span></button>`}<button class="mobile-menu-btn" data-action="mobile-menu">${icon('menu')}</button></div></div>${state.mobileMenu?`<nav class="mobile-nav">${navLink('home','Übersicht','home')}${navLink('module','Kurs','book-open')}${navLink('shop','Avatar-Welt','sparkles')}${navLink('test','Test','clipboard-check')}${navLink('checklist','Selbstcheck','list-checks')}${navLink('glossary','Glossar','book')}${state.account?.role==='teacher'?navLink('teacher','Lehrerbereich','users'):''}</nav>`:''}</header>`}
function footer(){return `<footer class="footer"><div class="footer-main"><span>${icon('scale')} RECHTSKLAR • Rechtsgeschäfte verstehen.</span><button class="text-button" data-nav="glossary">Begriffe & Rechtsquellen</button><button class="text-button" data-action="export-pdf">${icon('file-down')} Lernportfolio als PDF</button></div><p><strong>KI-Nachweis:</strong> Die Konzeption, Gestaltung und technische Überarbeitung dieses Kurses erfolgten am 05.11.2026 unter Nutzung von ChatGPT (GPT-6). Das KI-Werkzeug wurde insbesondere zur Strukturierung von Kursinhalten sowie zur Erstellung und Überarbeitung von HTML und CSS eingesetzt. Einzelne Grafiken wurden ebenfalls KI-gestützt erstellt. Die fachliche und redaktionelle Prüfung sowie die abschließende Auswahl und Anpassung der Inhalte <strong>liegen bei der kurserstellenden Lehrkraft und sind vor Unterrichtseinsatz vorzunehmen</strong>. Die Kennzeichnung orientiert sich an den Empfehlungen der Universität Hamburg zum Umgang mit generativer KI.</p><p class="tiny-disclaimer">Lernmaterial zur Vertiefung, keine individuelle Rechtsberatung. Gesetzesstand bei Erstellung: 05.11.2026. Nutzungsdaten werden mit Konto in Netlify Blobs, ohne Konto nur in diesem Browser gespeichert.</p></footer>`}
function sidebar(){return `<aside class="sidebar"><div class="side-title">${icon('map')} Lernpfad <span>${totalDone()}/${regularQuestions.length}</span></div>${progressBar(totalDone(),regularQuestions.length)}${chapters.map(c=>`<section class="side-ch"><div class="side-ch-title" style="--chapter-color:${c.color}">${icon(c.icon)} <span>${safe(c.name)}</span></div>${c.modules.map(id=>{const m=findMod(id),list=getItems(id),d=doneCount(list);return `<button class="module-link ${state.module===id&&state.page==='module'?'selected':''}" data-module="${id}"><span class="side-index">${m.index}</span><span class="modtext">${safe(m.title)}<small>${d}/${list.length} Aufgaben</small></span>${d===list.length?icon('circle-check','done-icon'):icon('chevron-right')}</button>`}).join('')}</section>`).join('')}<div class="side-ctas"><button class="button secondary block" data-nav="test">${icon('clipboard-list')} Abschlusstest</button><button class="button tertiary block" data-action="export-pdf">${icon('file-down')} Portfolio-PDF</button></div></aside>`}
function home(){let d=totalDone(),pc=Math.round(d*100/regularQuestions.length);return `<div class="home-content"><section class="hero"><div class="hero-copy"><div class="eyebrow">${icon('sparkles')} LERNEN • ANWENDEN • MEISTERN</div><h1>Rechtsgeschäfte?<br><span>Sie durchblicken das.</span></h1><p>Vom Chat-Angebot bis zur notariellen Beurkundung: Entscheiden Sie echte Fälle, sammeln Sie XP und gestalten Sie Ihren eigenen Avatar.</p><div class="hero-actions"><button class="button primary" data-module="w1">${icon('play')} ${d?'Kurs fortsetzen':'Lernkurs starten'}</button><button class="button ghost-light" data-nav="test">${icon('clipboard-check')} Zum Kompetenztest</button></div><div class="hero-micro"><span>${icon('shield-check')} Ohne Konto nutzbar</span><span>${icon('smartphone')} Mobil & Desktop</span><span>${icon('book-open')} ${regularQuestions.length} Übungen + ${testQuestions.length} Testfragen</span></div></div><div class="hero-art"><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div><div class="float-card card-one">${icon('check-circle-2')} Antrag + Annahme</div><div class="float-card card-two">${icon('zap')} +35 XP</div>${avatarGraphic('hero')}<div class="art-stars">✦ ✧</div></div></section>
 <div class="overview-top"><div><div class="eyebrow dark">IHR LERNSTAND</div><h2>Ihr Weg zum Rechtsprofi</h2></div><div class="completion-value">${pc}<span>% abgeschlossen</span></div></div>${progressBar(d,regularQuestions.length)}
 <div class="stats-grid"><div class="stat-card">${icon('check-check')}<strong>${d}</strong><span>Aufgaben gemeistert</span></div><div class="stat-card">${icon('zap')}<strong>${amt(state.progress.earned)}</strong><span>Gesammelte XP</span></div><div class="stat-card">${icon('award')}<strong>Level ${level()}</strong><span>Ihr aktuelles Level</span></div><div class="stat-card">${icon('gift')}<strong>${owned().size}</strong><span>Freigeschaltete Extras</span></div></div>
 <div class="section-heading"><div><div class="eyebrow dark">IHRE THEMEN</div><h2>Wählen Sie ein Kapitel</h2></div></div><div class="chapter-grid">${chapters.map((c,i)=>{let qs=regularQuestions.filter(q=>c.modules.includes(q.module)),dc=doneCount(qs);return `<button class="chapter-card theme-${c.id}" data-module="${c.modules[0]}"><div class="chapter-top"><span class="chapter-number">KAPITEL 0${i+1}</span>${icon(c.icon)}</div><div class="chapter-illustration illustration-${c.id}">${i===0?`${icon('message-square-text')}<span class="illustration-dot"></span>${icon('check-check')}`:i===1?`${icon('handshake')}${icon('arrow-left-right')}`:`${icon('file-signature')}${icon('stamp')}`}</div><h3>${safe(c.name)}</h3><p>${safe(c.subtitle)}</p><div class="chapter-footer">${progressBar(dc,qs.length)}<span>${dc}/${qs.length}</span></div></button>`}).join('')}</div>
 <div class="bottom-split"><section class="card-panel story-panel"><div class="eyebrow dark">DER ROTE FADEN</div><h2>Ein Fall begleitet Sie</h2><p>Mira macht eine Ausbildung bei <strong>ReRide</strong>, einer Werkstatt für gebrauchte Fahrräder und E-Bikes. Sie prüft Angebote, schließt Verträge und beschäftigt sich mit wichtigen Formvorschriften.</p><div class="story-flow"><span>${icon('message-circle')} Chat</span>${icon('arrow-right')}<span>${icon('handshake')} Vertrag</span>${icon('arrow-right')}<span>${icon('stamp')} Form</span></div><button class="button outline" data-module="r3">${icon('arrow-up-right')} Zum Vertragsfall</button></section><section class="card-panel achievements-panel"><div class="eyebrow dark">IHRE AUSZEICHNUNGEN</div><h2>Meilensteine</h2><div class="achievements">${badgeList()}</div></section></div>
 ${!state.account?`<div class="account-banner">${icon('cloud-upload')} <div><strong>Ohne Anmeldung direkt starten.</strong><span>Mit Nickname, Passwort und Klasse bleibt Ihr Fortschritt auch auf anderen Geräten verfügbar.</span></div><button class="button primary small" data-action="auth-modal">Konto anlegen</button></div>`:''}</div>`}
function moduleView(){let m=findMod(state.module),list=getItems(m.id),chapter=chapters.find(c=>c.id===m.chapter),d=doneCount(list);
 return `<div class="lesson"><div class="lesson-head"><div class="lesson-back"><button class="text-button" data-nav="home">${icon('arrow-left')} Übersicht</button><span>/</span><span>${safe(chapter.name)}</span></div><div class="eyebrow dark">LEKTION ${m.index} • KAPITEL ${chapter.id.toUpperCase()}</div><h1>${safe(m.title)}</h1><p>${safe(m.intro)}</p><div class="lesson-progress"><span>${icon('target')} ${d} von ${list.length} Übungen gelöst</span>${progressBar(d,list.length)}</div></div>
 <section class="story-callout"><div class="story-icon">${icon('bike')}</div><div><div class="small-caps">RE:RIDE • FORTLAUFENDER FALL</div><p>${safe(m.story)}</p></div></section>
 <div class="theory-section"><div class="section-title-with-icon">${icon('book-open-check')}<h2>Wissen für die Praxis</h2></div><div class="theory-grid">${m.theory.map((x,i)=>`<article class="theory-card"><div class="theory-idx">0${i+1}</div><h3>${safe(x.title)}</h3><p>${rich(x.body)}</p></article>`).join('')}</div><div class="takeaway">${icon('lightbulb')} <strong>Merksatz:</strong> ${safe(m.takeaway)}</div></div>
 <section class="diagram-card"><div class="diagram-header"><div><div class="eyebrow dark">ZUSAMMENHÄNGE ENTDECKEN</div><h2>Interaktives Schaubild</h2></div><span class="diagram-badge">${icon('mouse-pointer-click')} Antippen & ausprobieren</span></div>${renderDiagram(m.diagram)}</section>
 <section class="exercise-section"><div class="section-title-with-icon">${icon('swords')}<h2>Training: Fälle & Entscheidungen</h2><span class="task-count">${list.length} Aufgaben</span></div><p class="stack-hint">${icon('list-checks')} Alle Aufgaben stehen direkt untereinander. Sie können von oben nach unten arbeiten, Antworten prüfen und danach einfach weiterscrollen.</p><div class="tasks-stack">${list.map(t=>renderTask(t,list)).join('')}</div><div class="exercise-foot">${icon('info')} Wählen Sie bei Zuordnungsaufgaben eine Kategorie aus oder ziehen Sie die Karten auf den passenden Stapel. Auf Touch-Geräten funktioniert die Auswahl per Tipp.</div></section>
 <section class="more-lessons"><h3>Ihr nächster Lernschritt</h3>${(()=>{const idx=modules.findIndex(x=>x.id===m.id),next=modules[idx+1];return next?`<button class="button primary" data-module="${next.id}">${icon('arrow-right')} ${safe(next.title)}</button>`:`<button class="button primary" data-nav="test">${icon('graduation-cap')} Zum Abschlusstest</button>`})()}</section></div>`}
function renderDiagram(type){let value=state.diagram[type];
 const switchButtons=(opts,chosen)=>`<div class="diagram-tabs">${opts.map((t,i)=>`<button class="diagram-tab ${chosen===i?'active':''}" data-diagram="${type}" data-value="${i}">${safe(t)}</button>`).join('')}</div>`;
 if(type==='signal'){
 const v=Number(value??0),arr=[['„Schönes E-Bike!“','Nur eine Einschätzung, grundsätzlich ohne rechtsgeschäftlichen Bindungswillen.','message-circle'],['„Ich hätte gern irgendwann ein Rad.“','Ein Wunsch; der rechtsgeschäftliche Wille ist nicht hinreichend erkennbar.','heart'],['„Ich kaufe dieses Rad für 350 €.“','Kann ein Antrag und damit eine Willenserklärung sein.','check-circle-2']];return `${switchButtons(['Meinung','Wunsch','Kaufantrag'],v)}<div class="diagram-spotlight"><div class="diagram-spot-icon">${icon(arr[v][2])}</div><div><h3>${arr[v][0]}</h3><p>${arr[v][1]}</p></div></div>`}
 if(type==='expression'){
 const v=Number(value??0),arr=[['Ausdrücklich','„Ich bestelle diesen Reifen.“','Worte benennen den Willen unmittelbar.'],['Konkludent','Kundin legt den Reifen an die Kasse.','Das Verhalten lässt auf einen Kaufwunsch schließen.'],['Schweigen','Die Kundin antwortet nicht auf ein Angebot.','Grundsätzlich keine Annahmeerklärung.']];return `${switchButtons(['Ausdrücklich','Konkludent','Schweigen'],v)}<div class="visual-lanes"><div class="lane active">${icon('user-round')} Erklärende Person</div><div class="lane-arrow">${icon('arrow-right')}</div><div class="lane active">${icon('store')} Geschäft</div></div><div class="diagram-caption"><strong>${arr[v][0]}:</strong> ${arr[v][1]}<p>${arr[v][2]}</p></div>`}
 if(type==='access'){
 const v=Number(value??0),arr=[['Verfasst','Noch keine Zustellung an den Empfänger.'],['Abgesendet','Bloßes Absenden ist nicht immer Zugang.'],['Im Briefkasten','Zugang regelmäßig, wenn üblicherweise mit Kenntnisnahme zu rechnen ist.'],['Gelesen','Tatsächliches Lesen ist nicht stets erforderlich.']];return `${switchButtons(['Verfasst','Abgesendet','Briefkasten','Gelesen'],v)}<div class="flowline">${['file-edit','send','mailbox','eye'].map((ic,i)=>`<div class="flowstep ${i<=v?'hit':''}">${icon(ic)}<small>${arr[i][0]}</small></div>`).join('<div class="flow-connector"></div>')}</div><p class="diagram-caption">${arr[v][1]}</p>`}
 if(type==='unilateral'){
 const v=Number(value??0),arr=[['Kündigung','Empfangsbedürftig','Zugang beim Empfänger erforderlich.'],['Testament','Nicht empfangsbedürftig','Kein Zugang zu einer anderen Person nötig; eigenhändige Form beachten.'],['Auslobung','Nicht empfangsbedürftig','Öffentliche Bekanntmachung nach § 657 BGB.']];return `${switchButtons(['Kündigung','Testament','Auslobung'],v)}<div class="visual-lanes"><div class="lane active">${icon('user-round')} 1 Willenserklärung</div><div class="lane-arrow">${icon(v===0?'arrow-right':'arrow-up-right')}</div><div class="lane ${v===0?'active':''}">${icon(v===0?'user-round':'users-round')} ${v===0?'Empfänger':'Kein Empfänger nötig'}</div></div><div class="diagram-caption"><strong>${arr[v][0]} • ${arr[v][1]}</strong><p>${arr[v][2]}</p></div>`}
 if(type==='obligations'){
 const v=Number(value??0);return `${switchButtons(['Kaufvertrag','Schenkung'],v)}<div class="obligations"><div class="party">${icon('store')}<strong>${v===0?'Verkäufer':'Schenker'}</strong><span>${v===0?'Übergibt/übereignet Ware':'Gibt eine Sache unentgeltlich'}</span></div><div class="obligations-arrows"><span>→ ${v===0?'Ware':'Geschenk'} →</span>${v===0?'<span>← Kaufpreis ←</span>':'<span>← keine Gegenleistung</span>'}</div><div class="party">${icon('user-round')}<strong>${v===0?'Käufer':'Beschenkte Person'}</strong><span>${v===0?'Zahlt Kaufpreis, nimmt ab':'Nimmt Geschenk an'}</span></div></div><p class="diagram-caption">${v===0?'Zweiseitig verpflichtend: beide Vertragsparteien schulden Hauptleistungen.':'Einseitig verpflichtend: dennoch sind übereinstimmende Willenserklärungen nötig.'}</p>`}
 if(type==='contract'){
 const n=Number(value??350),match=n===350;return `<div class="contract-compare"><div class="contract-bubble">${icon('message-circle')}<small>Verkäuferin bietet an:</small><strong>350 €</strong></div><div class="contract-bubble right">${icon('message-circle')}<small>Mira antwortet:</small><strong>${n} €</strong></div></div><div class="slider-label"><span>Antwortpreis auswählen</span><strong>${n} €</strong></div><input aria-label="Antwortpreis" data-slider="contract" type="range" min="280" max="420" step="10" value="${n}"><div class="result-chip ${match?'good':'warn'}">${icon(match?'check-circle':'alert-circle')} ${match?'Preis stimmt überein – Annahme möglich.':'Preis weicht ab – grundsätzlich neuer Antrag (§ 150 Abs. 2 BGB).'}</div><p class="small-print">Vereinfachung: Weitere Vertragsmerkmale und Erklärungen müssen ebenfalls übereinstimmen.</p>`}
 if(type==='form'){
 const v=Number(value??0),arr=[['Gebrauchtes E-Bike kaufen','Grundsätzlich formfrei','Ein wirksamer Kaufvertrag kann z. B. mündlich entstehen.'],['Arbeitsverhältnis kündigen','Schriftform','Eigenhändige Unterschrift; gewöhnliche E-Mail genügt nicht.'],['Grundstück kaufen','Notarielle Beurkundung','Der Grundstückskaufvertrag muss beurkundet werden.'],['Modernisierungsmiete erhöhen','Textform','Zusätzlich müssen Berechnung und Erläuterung stimmen.']];return `${switchButtons(['E-Bike','Arbeitskündigung','Grundstück','Mieterhöhung'],v)}<div class="form-example"><span>${icon('file-text')}</span><div><small>Rechtsgeschäft</small><h3>${arr[v][0]}</h3><div class="result-chip good">${arr[v][1]}</div><p>${arr[v][2]}</p></div></div>`}
 if(type==='levels'){
 const v=Number(value??0),arr=[['Textform','Lesbar, Erklärende erkennbar; keine Unterschrift nötig.','mail'],['Schriftform','Grundsätzlich eigenhändige Namensunterschrift.','pen-tool'],['Öffentliche Beglaubigung','Insbesondere Unterschriftsechtheit wird amtlich bestätigt.','stamp'],['Notarielle Beurkundung','Notar nimmt Erklärungsinhalt auf und prüft/beurkundet.','scroll-text']];return `${switchButtons(arr.map(x=>x[0]),v)}<div class="form-stair">${arr.map((x,i)=>`<button class="stair-step ${i===v?'highlight':''}" data-diagram="levels" data-value="${i}" style="--stair:${i+1}">${icon(x[2])}<span>${x[0]}</span></button>`).join('')}</div><div class="diagram-caption"><strong>${arr[v][0]}</strong><p>${arr[v][1]}</p><small>Die Darstellung zeigt unterschiedliche gesetzliche Formanforderungen. Sie sind keine in jedem Fall austauschbaren „Schwierigkeitsstufen“.</small></div>`}
 if(type==='decision'){
 const v=Number(value??0),arr=[['Kaufvertrag über ein Grundstück per E-Mail','Notarielle Beurkundung fehlt → grundsätzlich nichtig; gesetzliche Heilung durch Auflassung und Grundbucheintragung möglich.','warn'],['Wohnraummietvertrag über zwei Jahre, nur mündlich','Nach § 550 BGB grundsätzlich unbefristet – nicht schon deshalb nichtig.','info'],['Fahrrad mündlich verschenkt und übergeben','Schenkungsversprechen: Formmangel kann durch tatsächliche Leistung geheilt sein (§ 518 Abs. 2 BGB).','good'],['Ausbildungsvertrag mündlich abgeschlossen','Vertrag kann wirksam sein; Ausbildende müssen wesentliche Inhalte in Textform dokumentieren (§ 11 BBiG).','info']];return `${switchButtons(['Grundstück','Wohnraum','Schenkung','Ausbildung'],v)}<div class="decision-flow"><div>${icon('search-check')} Welches Geschäft liegt vor?</div>${icon('arrow-down')}<div>${icon('file-check')} Welche besondere Regel gilt?</div>${icon('arrow-down')}<div class="decision-outcome ${arr[v][2]}">${arr[v][1]}</div></div>`}
 return '';
}
function answerReadable(q,answer){if(answer===undefined||answer===null)return '—';if(q.type==='single')return q.choices?.[answer]||'—';if(q.type==='truefalse')return answer?'Richtig':'Falsch';if(q.type==='multi')return toArray(answer).map(i=>q.choices?.[i]||'').join('; ');if(q.type==='classify')return q.items.map((item,i)=>`${item.label}: ${q.categories?.[answer?.[i]]||'—'}`).join('\n');if(q.type==='order')return toArray(answer).map(i=>q.items?.[i]||'').join(' → ');return String(answer||'—')}
function correctReadable(q){if(q.type==='open')return q.solution||q.why;if(q.type==='fill')return toArray(q.answer).length?toArray(q.answer).join(' / '):q.answer;return answerReadable(q,q.answer)}
function renderTask(q,qs){const ans=getAns(q),d=draft(q),idx=qs.findIndex(x=>x.id===q.id),feedback=state.reviewReady[q.id],shown=state.solutionShown[q.id]||ans?.solutionSeen;
 let control='';
 if(q.type==='single')control=`<div class="options-list">${q.choices.map((choice,i)=>`<label class="option ${d!==''&&Number(d)===i?'chosen':''}"><input type="radio" name="q-${q.id}" data-input="${q.id}" value="${i}" ${d!==''&&Number(d)===i?'checked':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${safe(choice)}</span></label>`).join('')}</div>`;
 if(q.type==='multi')control=`<div class="options-list">${q.choices.map((choice,i)=>`<label class="option ${toArray(d).includes(i)?'chosen':''}"><input type="checkbox" data-input="${q.id}" value="${i}" ${toArray(d).includes(i)?'checked':''}><span class="option-letter">${toArray(d).includes(i)?'✓':String.fromCharCode(65+i)}</span><span>${safe(choice)}</span></label>`).join('')}</div><p class="form-tip">Mehrere Antworten können richtig sein.</p>`;
 if(q.type==='truefalse')control=`<div class="tf-options"><label class="option ${d===true?'chosen':''}"><input type="radio" name="q-${q.id}" data-input="${q.id}" value="true" ${d===true?'checked':''}>${icon('check-circle-2')} Richtig</label><label class="option ${d===false?'chosen':''}"><input type="radio" name="q-${q.id}" data-input="${q.id}" value="false" ${d===false?'checked':''}>${icon('x-circle')} Falsch</label></div>`;
 if(q.type==='fill')control=`<label class="input-label">Ihre Antwort<input class="text-input answer-input" data-text="${q.id}" type="text" autocomplete="off" value="${safe(d)}" placeholder="Geben Sie den gesuchten Begriff ein."></label>`;
 if(q.type==='open')control=`<label class="input-label">Ihre Begründung / Falllösung<textarea class="textarea answer-input" data-text="${q.id}" rows="6" placeholder="Formulieren Sie Ihre Antwort in eigenen Worten.">${safe(d)}</textarea></label><div class="self-note">${icon('shield-check')} Längere Freitexte werden nicht automatisch bewertet. Vergleichen Sie Ihre Lösung selbst mit dem Erwartungshorizont.</div>`;
 if(q.type==='classify')control=`<div class="classification"><div class="categories">${q.categories.map((cat,i)=>`<div class="category-drop" data-drop="${q.id}" data-category="${i}"><strong>${safe(cat)}</strong><small>${q.items.filter((it,j)=>Number(d?.[j])===i).length} zugeordnet</small></div>`).join('')}</div><div class="sortable-cases">${q.items.map((it,i)=>`<div class="case-chip" draggable="true" data-drag="${q.id}" data-item="${i}"><div class="case-contents"><span class="drag-handle">${icon('grip-vertical')}</span><span>${safe(it.label)}</span></div><select aria-label="Kategorie für Fall ${i+1}" data-classify="${q.id}" data-item="${i}"><option value="-1" ${Number(d?.[i])<0?'selected':''}>Kategorie wählen …</option>${q.categories.map((c,j)=>`<option value="${j}" ${Number(d?.[i])===j?'selected':''}>${safe(c)}</option>`).join('')}</select></div>`).join('')}</div></div>`;
 if(q.type==='order')control=`<div class="order-list">${toArray(d).map((orig,pos)=>`<div class="order-row" draggable="true" data-orderdrag="${q.id}" data-pos="${pos}"><span class="order-nr">${pos+1}</span><span class="order-label">${safe(q.items[orig])}</span><button class="order-btn" data-order="${q.id}" data-index="${pos}" data-dir="up" aria-label="Nach oben">${icon('arrow-up')}</button><button class="order-btn" data-order="${q.id}" data-index="${pos}" data-dir="down" aria-label="Nach unten">${icon('arrow-down')}</button></div>`).join('')}</div><p class="form-tip">Verschieben Sie die Schritte per Pfeiltaste oder Drag-and-drop.</p>`;
 const status=ans?.correct?'done':ans?'pending':'';
 return `<article class="task-card" id="task-${q.id}" data-task-id="${q.id}"><div class="task-card-top"><div class="task-labels"><span class="small-badge">${q.test?'ABSCHLUSSTEST':q.bonus?'BONUSAUFGABE':`AUFGABE ${String(idx+1).padStart(2,'0')}`}</span><span class="afb-tag">AFB ${q.afb}</span><span class="xp-tag">${icon('zap')} ${xpFor(q)} XP</span></div>${ans?.correct?`<span class="solved-label">${icon('check-circle-2')} Gelöst</span>`:''}</div>${q.bonus?`<div class="bonus-banner">${icon('sparkles')} Extra-Herausforderung: Die Lösung erfordert eine begründete Entscheidung.</div>`:''}<h3>${safe(q.prompt)}</h3>${q.image?`<img class="source-illustration" src="${safe(q.image)}" alt="Rolleranzeige aus einem historischen Übungsfall">`:''}<div class="answer-area">${control}</div>
 ${q.type!=='open'&&q.afb>=2?`<label class="input-label reasoning-label">Ihre Begründung (freiwilliger Selbstcheck)<textarea class="textarea small-textarea" data-reason="${q.id}" rows="2" placeholder="Notieren Sie die Gründe für Ihre Entscheidung.">${safe(state.notes[q.id]??ans?.reason??'')}</textarea></label>`:''}
 ${feedback?`<div class="feedback ${feedback.kind}">${icon(feedback.kind==='good'?'check-circle-2':feedback.kind==='review'?'book-open-check':'lightbulb')}<div>${rich(feedback.text)}</div></div>`:ans?.correct?`<div class="feedback good">${icon('check-circle-2')} Sie haben diese Aufgabe bereits erfolgreich bearbeitet.</div>`:''}
 ${shown?`<div class="solution"><div class="solution-title">${icon('book-open-check')} Musterlösung / Erwartungshorizont</div><p>${rich(correctReadable(q)).replace(/\n/g,'<br>')}</p><div class="solution-why">${rich(q.why||q.solution||'')}</div><small>Bei Freitextaufgaben prüfen Sie selbst, ob Ihre Begründung die wesentlichen Kriterien erfüllt.</small></div>`:''}
 <div class="task-actions"><button class="button primary" data-action="submit" data-id="${q.id}" ${state.busy?'disabled':''}>${icon('check-circle-2')} ${q.type==='open'?'Antwort speichern':'Antwort prüfen'}</button><button class="button outline" data-action="ask-solution" data-id="${q.id}">${icon('eye')} Musterlösung ansehen</button>${q.type==='open'&&shown?`<button class="button accent" data-action="self-approve" data-id="${q.id}">${icon('badge-check')} Selbst als korrekt bewerten</button><button class="button tertiary" data-action="revise" data-id="${q.id}">${icon('pencil')} Antwort überarbeiten</button>`:''}</div>
</article>`}
function shop(){let filter=state.shopFilter;let types=[['all','Alle Extras'],['outfit','Outfits'],['pet','Haustiere'],['back','Kulissen']];return `<div class="page-shell"><div class="page-head"><div class="eyebrow dark">LEVEL ${level()} • FREISCHALTUNGEN</div><h1>Ihr Avatar. Ihre Entscheidungen.</h1><p>Lösen Sie Aufgaben, verdienen Sie XP und gestalten Sie Ihren persönlichen Lerncharakter. Gekaufte Artikel bleiben dauerhaft in Ihrer Galerie.</p></div><div class="gallery-header"><div class="gallery-scene">${avatarGraphic('gallery')}<div class="gallery-text"><strong>${safe(state.account?.nick||'Gastcharakter')}</strong><span>Level ${level()} • ${amt(balance())} XP verfügbar</span></div></div><div class="gallery-stats"><div>${icon('zap')}<span><strong>${amt(state.progress.earned)}</strong> insgesamt verdient</span></div><div>${icon('shopping-bag')}<span><strong>${amt(state.progress.spent)}</strong> XP ausgegeben</span></div><div>${icon('package-check')}<span><strong>${owned().size}</strong> Artikel im Besitz</span></div><p>Die verdienten XP bestimmen Ihr Level. Bei Einkäufen sinken nur Ihre verfügbaren XP, nicht Ihr Level.</p></div></div><h2>Freischaltbare Extras</h2><div class="shop-tabs">${types.map(([id,label])=>`<button class="tab ${filter===id?'active':''}" data-filter="${id}">${label}</button>`).join('')}</div><div class="shop-grid">${shopItems.filter(x=>filter==='all'||x.type===filter).map(item=>{let has=owned().has(item.id),eq=state.progress.equipped?.[item.type]===item.id;return `<div class="shop-card ${has?'owned':''}"><div class="shop-img ${item.type} ${item.id}"><span>${icon(item.icon)}</span>${has?`<div class="owned-flag">${icon('check')} Im Besitz</div>`:''}</div><h3>${safe(item.name)}</h3><p>${safe(item.desc)}</p><div class="shop-bottom"><span class="cost">${icon('zap')} ${item.cost?' '+item.cost+' XP':' Gratis'}</span>${eq?`<span class="equipped">Ausgerüstet</span>`:has?`<button class="button small secondary" data-action="equip" data-id="${item.id}">Anlegen</button>`:`<button class="button small ${balance()>=item.cost?'primary':'outline'}" data-action="buy" data-id="${item.id}" ${balance()<item.cost?'disabled':''}>Freischalten</button>`}</div></div>`}).join('')}</div></div>`}
function testView(){let d=doneCount(testQuestions),pct=Math.round(100*d/testQuestions.length);return `<div class="page-shell"><div class="page-head"><div class="eyebrow dark">IHR KOMPETENZ-CHECK</div><h1>Das große Finale</h1><p>Prüfen Sie, ob Sie Willenserklärungen, Arten von Rechtsgeschäften und Formvorschriften sicher auf Fälle anwenden können. Der Abschlusstest lässt sich beliebig wiederholen.</p></div><div class="test-banner"><div class="test-icon">${icon('graduation-cap')}</div><div><strong>${d} von ${testQuestions.length} Fragen gelöst</strong>${progressBar(d,testQuestions.length)}</div><div class="test-score">${pct}<small>%</small></div></div><p class="stack-hint">${icon('list-checks')} Alle Testfragen sind direkt sichtbar. Bearbeiten Sie sie nacheinander.</p><div class="tasks-stack">${testQuestions.map(q=>renderTask(q,testQuestions)).join('')}</div>${d===testQuestions.length?`<div class="graduation-message">${icon('trophy')} <div><h2>Kompetenztest gemeistert!</h2><p>Ihre Ergebnisse können Sie im Lernportfolio als PDF sichern. Schätzen Sie jetzt Ihre Kompetenzen in der Checkliste ein.</p></div><button class="button primary" data-nav="checklist">Selbstcheck</button></div>`:''}</div>`}
function checklist(){const objs=competencies.map((s,i)=>({text:s,i,entry:state.progress.checklist?.[i]}));const todo=objs.filter(x=>!x.entry?.done),done=objs.filter(x=>x.entry?.done);return `<div class="page-shell"><div class="page-head"><div class="eyebrow dark">REFLEXION</div><h1>Was können Sie bereits?</h1><p>Schätzen Sie jede Kompetenz auf einer Skala von 1 bis 5 ein. Markieren Sie einen Eintrag als erledigt – und setzen Sie ihn jederzeit zurück.</p></div><div class="checklist-overview">${icon('list-checks')} <strong>${done.length}/${competencies.length} Kompetenzen erledigt</strong>${progressBar(done.length,competencies.length)}</div>${[['Noch offen',todo],['Erledigt',done]].map(([name,entries])=>`<section class="check-group"><h2>${name} <span>(${entries.length})</span></h2>${entries.length?entries.map(({text,i,entry})=>`<div class="competency ${entry?.done?'completed':''}"><div class="competency-head"><strong>${safe(text)}</strong><label class="done-toggle"><input type="checkbox" data-check="${i}" ${entry?.done?'checked':''}><span>${entry?.done?'Erledigt':'Als erledigt markieren'}</span></label></div><div class="rating"><span>Selbsteinschätzung</span><div class="rating-buttons">${[1,2,3,4,5].map(j=>`<button class="rating-button ${(entry?.rating||0)===j?'chosen':''}" data-rating="${i}" data-value="${j}">${j}</button>`).join('')}</div><small>1 = noch unsicher · 5 = sehr sicher</small></div></div>`).join(''):`<p class="empty-hint">In dieser Kategorie befinden sich aktuell keine Einträge.</p>`}</section>`).join('')}</div>`}
function glossaryView(){const v=state.glossarySearch.trim().toLocaleLowerCase('de-DE');return `<div class="page-shell"><div class="page-head"><div class="eyebrow dark">NACHSCHLAGEN</div><h1>Begriffslexikon</h1><p>Wichtige Fachbegriffe und weiterführende Rechtsquellen für Ihre Fallbearbeitung.</p></div><div class="search-wrap">${icon('search')}<input id="glossary-search" type="search" placeholder="Begriff suchen …" value="${safe(state.glossarySearch)}"></div><div class="glossary-grid">${glossary.filter(x=>(x[0]+' '+x[1]).toLocaleLowerCase('de-DE').includes(v)).map(([term,def])=>`<div class="glossary-item"><h3>${safe(term)}</h3><p>${safe(def)}</p></div>`).join('')||'<p>Kein Begriff gefunden.</p>'}</div><section class="source-links"><h2>Gesetzliche Grundlagen</h2><p>Die amtlichen Fassungen können Sie bei Bedarf zur Vertiefung nutzen.</p><div class="link-grid">${sources.legal.map(([name,url])=>`<a href="${safe(url)}" target="_blank" rel="noopener noreferrer">${icon('external-link')} ${safe(name)}</a>`).join('')}</div><h2>Zusätzliche Lernressourcen</h2><div class="link-grid">${sources.extras.map(([name,url])=>`<a href="${safe(url)}" target="_blank" rel="noopener noreferrer">${icon('external-link')} ${safe(name)}</a>`).join('')}</div></section></div>`}
function profileView(){return `<div class="page-shell"><div class="page-head"><div class="eyebrow dark">IHR KONTO</div><h1>${state.account?'Profil & Einstellungen':'Gastmodus'}</h1></div>${state.account?`<div class="profile-panel"><div class="profile-visual">${avatarGraphic('gallery')}</div><div><h2>${safe(state.account.nick)}</h2><p>${icon('users')} Klasse: <strong>${safe(state.account.klass)}</strong> · Rolle: ${state.account.role==='teacher'?'Lehrkraft':'Schülerkonto'}</p><p>${icon('cloud-check')} Ihr Lernstand wird geräteübergreifend in Netlify Blobs gespeichert.</p><button class="button outline" data-action="logout">${icon('log-out')} Abmelden</button></div></div><section class="card-panel password-card"><h2>Passwort ändern ${state.account.mustChangePassword?'• Jetzt erforderlich':''}</h2><p>Nach einem Passwort-Reset durch die Lehrkraft sollten Sie sofort ein eigenes Passwort festlegen.</p><form id="password-form"><label class="input-label">Aktuelles Passwort<input type="password" name="current" autocomplete="current-password" required></label><label class="input-label">Neues Passwort (mindestens 8 Zeichen)<input type="password" name="password" minlength="8" autocomplete="new-password" required></label><button class="button primary" type="submit">Passwort ändern</button></form></section>`:`<div class="card-panel"><p>Im Gastmodus wird Ihr Fortschritt nur lokal in diesem Browser gespeichert. Sie können jederzeit ein Konto für geräteübergreifende Speicherung erstellen.</p><button class="button primary" data-action="auth-modal">Anmelden oder registrieren</button></div>`}<section class="card-panel profile-export"><h2>Ihr Lernportfolio</h2><p>Exportieren Sie alle bereits bearbeiteten Aufgaben einschließlich Ihrer eigenen Antworten und Begründungen als zusammenhängendes PDF.</p><button class="button primary" data-action="export-pdf">${icon('file-down')} Persönliches Portfolio herunterladen</button></section></div>`}
function teacherView(){const arr=state.teacherRows;const name=state.teacherSelected;const sel=arr.find(x=>x.nick===name);return `<div class="page-shell teacher-page"><div class="page-head"><div class="eyebrow dark">LEHRKRAFT • ${safe(state.account?.klass)}</div><h1>Lernfortschritt verwalten</h1><p>Sie sehen ausschließlich Lernende, die derselben Klasse zugeordnet sind. Hier können Sie Ergebnisse prüfen, Passwörter zurücksetzen und Konten oder Fortschritte löschen.</p></div><div class="teacher-controls"><button class="button primary" data-action="teacher-refresh">${icon('refresh-cw')} Aktualisieren</button><button class="button danger-outline" data-action="reset-all">${icon('trash-2')} Klassenfortschritt zurücksetzen</button><span>Schülerkonten: ${arr.length}</span></div><div class="teacher-stats">${[['Personen',arr.length,'users'],['Gelöste Aufgaben',arr.reduce((a,u)=>a+u.done,0),'check-check'],['XP gesamt',arr.reduce((a,u)=>a+u.earned,0),'zap']].map(([lab,n,ic])=>`<div>${icon(ic)} <strong>${amt(n)}</strong><span>${lab}</span></div>`).join('')}</div>${arr.length?`<div class="teacher-table-wrap"><table class="teacher-table"><thead><tr><th>Nickname</th><th>Aufgaben</th><th>XP gesamt</th><th>Zuletzt</th><th>Aktion</th></tr></thead><tbody>${arr.map(u=>`<tr><td><strong>${safe(u.nick)}</strong></td><td>${u.done} / ${regularQuestions.length+testQuestions.length}</td><td>${amt(u.earned)}</td><td>${u.last?date(u.last):'—'}</td><td><button class="button small outline" data-action="student-detail" data-id="${safe(u.nick)}">Ansehen ${icon('chevron-right')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state">${icon('users')} Für diese Klasse liegen noch keine Schülerkonten vor.</div>`}${sel?`<section class="student-detail card-panel"><div class="detail-title"><h2>${safe(sel.nick)} – Lernprofil</h2><button class="text-button" data-action="close-student">${icon('x')} Schließen</button></div><p>${sel.done} gelöste Aufgaben · ${sel.earned} XP insgesamt · Registrierung: ${date(sel.created)}</p><div class="teacher-actions"><button class="button outline" data-action="reset-student" data-id="${safe(sel.nick)}">${icon('rotate-ccw')} Fortschritt löschen</button><button class="button outline" data-action="reset-password" data-id="${safe(sel.nick)}">${icon('key-round')} Passwort zurücksetzen</button><button class="button danger-outline" data-action="delete-student" data-id="${safe(sel.nick)}">${icon('user-x')} Nutzer entfernen</button></div><h3>Aufgabenübersicht</h3><div class="detail-answers">${Object.entries(sel.answered||{}).sort((a,b)=>(b[1].date||0)-(a[1].date||0)).map(([id,entry])=>{const q=questionById[id];if(!q||entry.answer===undefined)return '';return `<details><summary>${entry.correct?'✓':'•'} ${safe(q.prompt.slice(0,100))} <small>${date(entry.date)}</small></summary><strong>Antwort:</strong><p>${safe(answerReadable(q,entry.answer)).replace(/\n/g,'<br>')}</p>${entry.reason?`<strong>Begründung:</strong><p>${safe(entry.reason)}</p>`:''}</details>`}).join('')||'<p>Noch keine Antworten vorhanden.</p>'}</div></section>`:''}</div>`}
function modal(){if(!state.modal)return '';let m=state.modal;let body='';if(m.type==='auth'){body=`<div class="auth-head"><div class="auth-icon">${icon('shield-check')}</div><h2>Bei RECHTSKLAR anmelden</h2><p>Ein Konto speichert Ihre Ergebnisse geräteübergreifend. Ohne Konto können Sie den Kurs sofort nutzen.</p></div><div class="auth-tabs"><button class="tab ${state.mode==='login'?'active':''}" data-auth-mode="login">Anmelden</button><button class="tab ${state.mode==='register'?'active':''}" data-auth-mode="register">Registrieren</button></div>${state.mode==='register'?`<div class="role-tabs"><label><input type="radio" name="role" value="student" ${state.tab==='student'?'checked':''} data-role="student"> Schüler/in</label><label><input type="radio" name="role" value="teacher" ${state.tab==='teacher'?'checked':''} data-role="teacher"> Lehrkraft</label></div>`:''}<form id="auth-form"><label class="input-label">Klasse<input type="text" name="klass" maxlength="40" placeholder="z. B. BG12A" required></label><label class="input-label">Nickname<input type="text" name="nick" maxlength="24" placeholder="Ihr selbstgewählter Nickname" required></label><label class="input-label">Passwort<input type="password" name="password" minlength="8" maxlength="128" placeholder="Mindestens 8 Zeichen" required autocomplete="${state.mode==='register'?'new-password':'current-password'}"></label>${state.mode==='register'&&state.tab==='teacher'?`<label class="input-label">Lehrkraft-Code<input type="password" name="teacherCode" placeholder="In Netlify hinterlegter Einrichtungscode" required></label>`:''}<button class="button primary block" type="submit" ${state.busy?'disabled':''}>${icon(state.mode==='login'?'log-in':'user-plus')} ${state.mode==='login'?'Anmelden':'Konto erstellen'}</button></form><p class="auth-foot">${state.mode==='register'&&state.tab==='student'?'Die Lehrkraft muss die Klasse zuerst angelegt haben.':''} Keine E-Mail-Adresse erforderlich.</p><button class="text-button auth-skip" data-action="modal-close">Ohne Konto weiterlernen</button>`}
 if(m.type==='solution'){const q=questionById[m.id];body=`<div class="modal-art">${icon('eye')}</div><h2>Bereit für die Musterlösung?</h2><p>Sie können die Aufgabe zunächst noch einmal selbst lösen. Wenn Sie jetzt die Lösung ansehen, wird dies in Ihrem Lernstand vermerkt.</p><div class="modal-buttons"><button class="button outline" data-action="modal-close">Ich versuche es erneut</button><button class="button primary" data-action="reveal-solution" data-id="${q.id}">Ja, Musterlösung zeigen</button></div>`}
 if(m.type==='confirm'){body=`<div class="modal-art warning">${icon('alert-triangle')}</div><h2>${safe(m.title)}</h2><p>${safe(m.message)}</p>${m.phrase?`<label class="input-label">Zur Bestätigung exakt eingeben:<strong>${safe(m.phrase)}</strong><input id="confirm-text" type="text" placeholder="Bestätigung eingeben"></label>`:''}<div class="modal-buttons"><button class="button outline" data-action="modal-close">Abbrechen</button><button class="button danger" data-action="confirm-danger">${safe(m.button||'Endgültig bestätigen')}</button></div>`}
 if(m.type==='password'){body=`<div class="modal-art">${icon('key-round')}</div><h2>Temporäres Passwort</h2><p>Übergeben Sie dieses Passwort ausschließlich der betreffenden Person. Es wird nur hier einmal angezeigt.</p><div class="temp-pass"><code>${safe(state.teacherPassword)}</code><button class="button small secondary" data-action="copy-pass">${icon('copy')} Kopieren</button></div><p>Beim nächsten Login soll die Person im Profil ihr Passwort ändern.</p><button class="button primary" data-action="modal-close">Schließen</button>`}
 return `<div class="modal-backdrop" data-action="backdrop"><div class="modal" role="dialog" aria-modal="true"><button class="modal-x" data-action="modal-close" aria-label="Schließen">${icon('x')}</button>${body}</div></div>`}
function render(){let inner='';if(state.page==='home')inner=home();else if(state.page==='module')inner=moduleView();else if(state.page==='shop')inner=shop();else if(state.page==='test')inner=testView();else if(state.page==='checklist')inner=checklist();else if(state.page==='glossary')inner=glossaryView();else if(state.page==='profile')inner=profileView();else if(state.page==='teacher')inner=state.account?.role==='teacher'?teacherView():home();else inner=home();const anchored=taskAnchor&&document.getElementById(`task-${taskAnchor}`);
 const previousY=anchored?.getBoundingClientRect().top;
 root.innerHTML=`${header()}<div class="app-wrapper">${sidebar()}<main class="main-content" id="main">${inner}</main></div>${footer()}${state.account?.mustChangePassword&&state.page!=='profile'?`<div class="password-banner">${icon('alert-circle')} Bitte ändern Sie Ihr vorläufiges Passwort im Profil. <button data-nav="profile">Jetzt ändern</button></div>`:''}${state.notice?`<div class="toast ${state.notice.bad?'error':''}">${icon(state.notice.bad?'alert-circle':'check-circle-2')} ${safe(state.notice.text)}</div>`:''}${modal()}`;renderIcon();
 if(taskAnchor&&previousY!==undefined){const newTask=document.getElementById(`task-${taskAnchor}`);if(newTask){const diff=newTask.getBoundingClientRect().top-previousY;if(Math.abs(diff)>1)window.scrollBy({top:diff,behavior:'instant'});}}
 taskAnchor=null;
}
async function api(path,body,method='POST'){
 try{const response=await fetch(`/api/${path}`,{method,credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error||`Fehler ${response.status}`);return data}
 catch(e){throw new Error(e.message==='Failed to fetch'?'Server nicht erreichbar. Die Anmeldung benötigt Netlify Functions (im lokalen Vite-Modus steht nur der Gastmodus bereit).':e.message)}
}
async function syncAction(path,body){if(state.account){const data=await api(path,body);if(data.progress)state.progress=data.progress;if(data.user)state.account=data.user;return data}return null}
async function submit(q,approved=false){
 const answer=draft(q);
 if(q.type==='open'&&String(answer??'').trim().length<12){note('Bitte formulieren Sie zunächst eine eigene Antwort (mindestens 12 Zeichen).',true);return}
 if(q.type==='single'&&(answer===''||answer===null||answer===undefined)){note('Wählen Sie eine Antwort aus.',true);return}
 if(q.type==='truefalse'&&answer===null){note('Entscheiden Sie sich für Richtig oder Falsch.',true);return}
 if(q.type==='multi'&&(!Array.isArray(answer)||!answer.length)){note('Wählen Sie mindestens eine Antwort aus.',true);return}
 if(q.type==='classify'&&(!Array.isArray(answer)||answer.some(v=>v<0))){note('Ordnen Sie erst alle Fälle einer Kategorie zu.',true);return}
 const correct=judge(q,answer,approved);const reason=state.notes[q.id]??getAns(q)?.reason??'';
 state.busy=true;try{
  if(state.account){const data=await api('submit',{id:q.id,answer,approved,reason});state.progress=data.progress;const ok=data.correct;if(q.type==='open'){state.reviewReady[q.id]={kind:approved&&ok?'good':'review',text:approved&&ok?'Ihre Selbsteinschätzung wurde gespeichert.':'Ihre Antwort ist gespeichert. Lesen Sie anschließend die Musterlösung und beurteilen Sie Ihre Antwort selbst.'}}else{state.reviewReady[q.id]={kind:ok?'good':'retry',text:ok?`Richtig! ${data.earnedNow?`+${data.earnedNow} XP`: 'Bereits als gelöst gespeichert.'} ${q.why}`:`Noch nicht ganz. Prüfen Sie Ihre Einordnung und versuchen Sie es erneut. Sie können auch die Musterlösung aufrufen.`}}}
  else{
   const p=state.progress,old=p.answers[q.id],reward=correct&&!old?.correct?xpFor(q):0;
   p.answers[q.id]={answer,reason,correct:!!(correct||old?.correct),latestCorrect:correct,awarded:(old?.awarded||0)+reward,tries:(old?.tries||0)+1,date:Date.now(),solutionSeen:!!old?.solutionSeen,selfReviewed:!!((approved&&correct&&(state.solutionShown[q.id]||getAns(q)?.solutionSeen))||old?.selfReviewed)};p.earned+=reward;
   saveGuest();if(q.type==='open')state.reviewReady[q.id]={kind:approved&&correct?'good':'review',text:approved&&correct?'Ihre Selbsteinschätzung wurde gespeichert.':'Ihre Antwort ist gespeichert. Vergleichen Sie sie mit der Musterlösung.'};else state.reviewReady[q.id]={kind:correct?'good':'retry',text:correct?`Richtig! ${reward?`+${reward} XP`: 'Bereits gelöst.'} ${q.why}`:'Noch nicht korrekt. Sie können Ihre Antwort überarbeiten oder die Musterlösung ansehen.'};
  }
 }catch(e){note(e.message,true)}finally{state.busy=false;render()}
}
async function showSolution(id){state.solutionShown[id]=true;state.modal=null;if(state.account){try{await syncAction('solution',{id})}catch(e){note(e.message,true)}}else{state.progress.answers[id]={...(state.progress.answers[id]||{}),solutionSeen:true};saveGuest()}render()}
async function buy(id){const item=shopItems.find(x=>x.id===id);if(!item)return;if(!owned().has(id)&&balance()<item.cost)return note('Sie benötigen mehr XP für diesen Artikel.',true);
 try{if(state.account)await syncAction('buy',{id});else if(!owned().has(id)){state.progress.owned.push(id);state.progress.spent+=item.cost;saveGuest()};note(`${item.name} ist jetzt in Ihrer Galerie.`)}catch(e){note(e.message,true)} }
async function equip(id){let item=shopItems.find(x=>x.id===id);if(!item)return;try{if(state.account)await syncAction('equip',{id});else{state.progress.equipped[item.type]=item.id;saveGuest()};render()}catch(e){note(e.message,true)}}
async function checklistSet(i,part,val){const p=state.progress,old=p.checklist[i]||{rating:3,done:false},next={...old,[part]:val};try{if(state.account)await syncAction('checklist',{index:i,...next});else{p.checklist[i]=next;saveGuest()};render()}catch(e){note(e.message,true)}}
async function authSubmit(form){const b=Object.fromEntries(new FormData(form));if(state.mode==='register'){b.role=state.tab;b.teacherCode=b.teacherCode||'';}try{state.busy=true;const data=await api(state.mode==='login'?'login':'register',b);const guestCopy=JSON.parse(localStorage.getItem(GUEST_KEY)||'null');state.account=data.user;state.progress=data.progress;state.modal=null;state.busy=false;if(guestCopy&&(Object.keys(guestCopy.answers||{}).length||Object.keys(guestCopy.checklist||{}).length)){try{const merged=await api('import',{answers:guestCopy.answers,owned:guestCopy.owned,equipped:guestCopy.equipped,checklist:guestCopy.checklist});state.progress=merged.progress;localStorage.removeItem(GUEST_KEY)}catch(e){note('Anmeldung erfolgreich. Gastdaten konnten nicht vollständig importiert werden: '+e.message,true)}}route('home');note(`Willkommen, ${state.account.nick}. Fortschritt wird jetzt online gespeichert.`);if(state.account.role==='teacher')loadTeacher()}catch(e){state.busy=false;note(e.message,true)}}
async function logout(){try{await api('logout',{});state.account=null;let g;try{g=JSON.parse(localStorage.getItem(GUEST_KEY)||'null')}catch{}state.progress=g||defaultProgress();state.teacherRows=[];route('home');note('Sie wurden abgemeldet.')}catch(e){note(e.message,true)}}
async function loadTeacher(){try{const data=await api('students',undefined,'GET');state.teacherRows=data.users||[];render()}catch(e){note(e.message,true)}}
async function dangerPerform(m){if(m.phrase&&document.getElementById('confirm-text')?.value!==m.phrase){note('Bitte die vorgegebene Bestätigung exakt eingeben.',true);return}state.modal=null;try{if(m.kind==='reset-all'){const result=await api('reset-progress',{all:true,confirm:m.phrase});note(`Lernfortschritt von ${result.count} Konten gelöscht.`)}else if(m.kind==='reset-student'){await api('reset-progress',{nick:m.nick});note(`Fortschritt von ${m.nick} zurückgesetzt.`)}else if(m.kind==='delete-student'){await api('delete-user',{nick:m.nick});state.teacherSelected=null;note(`Konto ${m.nick} entfernt.`)}else if(m.kind==='reset-password'){const r=await api('reset-password',{nick:m.nick});state.teacherPassword=r.temporary;state.modal={type:'password'}}await loadTeacher()}catch(e){note(e.message,true)}}
function exportPDF(){const list=[...regularQuestions,...testQuestions].filter(q=>state.progress.answers?.[q.id]?.answer!==undefined);if(!list.length){note('Bearbeiten Sie zuerst mindestens eine Aufgabe.',true);return}
 const doc=new jsPDF({unit:'mm',format:'a4',compress:true});const max=182,left=15,right=15;let y=21,page=1;
 function newpage(){doc.addPage();page++;y=18}
 function paragraph(text,fontSize=10,weight='normal',gap=4){doc.setFont('helvetica',weight);doc.setFontSize(fontSize);const lines=doc.splitTextToSize(String(text||'—'),max);for(const l of lines){if(y>278)newpage();doc.text(l,left,y);y+=fontSize*0.48+0.7;}y+=gap;}
 function label(text){if(y>265)newpage();doc.setDrawColor(210,218,232);doc.line(left,y-1,195,y-1);y+=6;paragraph(text,9,'bold',1)}
 doc.setFillColor(13,26,56);doc.rect(0,0,210,49,'F');doc.setTextColor(255,255,255);doc.setFontSize(22);doc.setFont('helvetica','bold');doc.text('RECHTSKLAR',15,23);doc.setFont('helvetica','normal');doc.setFontSize(10);doc.text('Lernportfolio: bearbeitete Aufgaben und eigene Antworten',15,32);doc.setTextColor(28,38,65);y=61;
 paragraph(`Name: ${state.account?.nick||'Gastkonto'}    Klasse: ${state.account?.klass||'Nicht angegeben'}`,11,'bold',3);
 paragraph(`Erstellt am: ${new Date().toLocaleDateString('de-DE')} | Aufgaben: ${list.length} | Davon korrekt / selbst bestätigt: ${doneCount(list)}`,10,'normal',4);
 paragraph('Freitextantworten beruhen auf eigener Selbsteinschätzung. Dieses Portfolio enthält Antworten, keine automatische Benotung.',9,'normal',6);
 for(const [i,q] of list.entries()){
  const a=state.progress.answers[q.id],mod=findMod(q.module);label(`${i+1}. ${mod.title} | ${q.test?'Test':q.bonus?'Bonus':'Übung'} | AFB ${q.afb}`);
  paragraph(q.prompt,10,'bold',3);
  paragraph('Ihre Antwort:',9,'bold',1);paragraph(answerReadable(q,a.answer),10,'normal',3);
  if(a.reason){paragraph('Ihre Begründung:',9,'bold',1);paragraph(a.reason,9,'normal',3)}
  paragraph(`Bearbeitungsstatus: ${a.correct?'gelöst / bestätigt':'noch offen'}${a.solutionSeen?' | Musterlösung aufgerufen':''}`,9,'normal',7);
 }
 const pages=doc.internal.getNumberOfPages();for(let i=1;i<=pages;i++){doc.setPage(i);doc.setFontSize(8);doc.setTextColor(130,137,154);doc.text(`RECHTSKLAR · ${i}/${pages}`,195,289,{align:'right'});}doc.save(`Rechtsklar_Lernportfolio_${(state.account?.nick||'Gast').replace(/[^\w-]/g,'_')}.pdf`);note(`PDF mit ${list.length} bearbeiteten Aufgaben wurde erstellt.`);
}
root.addEventListener('click',async e=>{
 setTaskAnchor(e.target);
 const nav=e.target.closest('[data-nav]');if(nav){state.mobileMenu=false;route(nav.dataset.nav,state.module);return}
 const m=e.target.closest('[data-module]');if(m){state.mobileMenu=false;state.question=null;route('module',m.dataset.module);return}
 const qBtn=e.target.closest('[data-question]');if(qBtn){state.question=qBtn.dataset.question;const q=questionById[state.question];route(q.test?'test':'module',q.module,q.id);return}
 const dia=e.target.closest('[data-diagram]');if(dia){state.diagram[dia.dataset.diagram]=Number(dia.dataset.value);render();return}
 const fil=e.target.closest('[data-filter]');if(fil){state.shopFilter=fil.dataset.filter;render();return}
 const am=e.target.closest('[data-auth-mode]');if(am){state.mode=am.dataset.authMode;render();return}
 const action=e.target.closest('[data-action]');const a=action?.dataset.action,id=action?.dataset.id;
 if(a==='auth-modal'){state.modal={type:'auth'};render()}
 else if(a==='modal-close'){state.modal=null;render()}
 else if(a==='mobile-menu'){state.mobileMenu=!state.mobileMenu;render()}
 else if(a==='submit')await submit(questionById[id]);
 else if(a==='self-approve')await submit(questionById[id],true);
 else if(a==='ask-solution'){state.modal={type:'solution',id};render()}
 else if(a==='reveal-solution')await showSolution(id);
 else if(a==='revise'){state.reviewReady[id]=null;state.solutionShown[id]=false;render();}
 else if(a==='buy')await buy(id);
 else if(a==='equip')await equip(id);
 else if(a==='export-pdf')exportPDF();
 else if(a==='logout')await logout();
 else if(a==='student-detail'){state.teacherSelected=id;render();document.querySelector('.student-detail')?.scrollIntoView({behavior:'smooth'})}
 else if(a==='teacher-refresh')await loadTeacher();
 else if(a==='close-student'){state.teacherSelected=null;render()}
 else if(a==='copy-pass')await navigator.clipboard?.writeText(state.teacherPassword||'');
 else if(a==='reset-all'){state.modal={type:'confirm',title:'Gesamten Klassenfortschritt löschen?',message:'Alle Schüler-Lernstände, verdienten XP, Käufe und Selbsteinschätzungen dieser Klasse werden unwiderruflich gelöscht. Konten und Passwörter bleiben bestehen.',phrase:`ALLE ${state.account.klass}`,button:'Klassenfortschritt löschen',kind:'reset-all'};render()}
 else if(a==='reset-student'||a==='delete-student'||a==='reset-password'){
  const kind=a,subject=id;
  state.modal={type:'confirm',title:a==='delete-student'?'Schülerkonto löschen?':a==='reset-password'?'Passwort zurücksetzen?':'Lernfortschritt löschen?',message:a==='delete-student'?`Das Konto „${subject}“ mit allen Daten wird gelöscht.`:a==='reset-password'?`Für „${subject}“ wird ein neues temporäres Passwort erstellt.`:`Alle Aufgabenstände und XP von „${subject}“ werden gelöscht.`,button:a==='delete-student'?'Konto löschen':a==='reset-password'?'Neues Passwort erstellen':'Fortschritt löschen',kind,nick:subject,phrase:a==='delete-student'?`LÖSCHEN ${subject}`:undefined};render();
 }
 else if(a==='confirm-danger')await dangerPerform(state.modal);
 else if(a==='backdrop'&&e.target===action){state.modal=null;render()}
 const ord=e.target.closest('[data-order]');if(ord){const q=questionById[ord.dataset.order],d=toArray(draft(q)).slice(),idx=Number(ord.dataset.index),to=ord.dataset.dir==='up'?idx-1:idx+1;if(to>=0&&to<d.length){[d[idx],d[to]]=[d[to],d[idx]];setDraft(q.id,d);render()}return}
 const r=e.target.closest('[data-rating]');if(r){await checklistSet(Number(r.dataset.rating),'rating',Number(r.dataset.value));return}
});
root.addEventListener('change',e=>{
 setTaskAnchor(e.target);
 const el=e.target;
 if(el.matches('[data-role]')){state.tab=el.value;render();return}
 if(el.matches('[data-input]')){let id=el.dataset.input,q=questionById[id],d=draft(q);if(q.type==='single')setDraft(id,Number(el.value));else if(q.type==='truefalse')setDraft(id,el.value==='true');else if(q.type==='multi'){let a=toArray(d).slice(),v=Number(el.value);if(el.checked&&!a.includes(v))a.push(v);if(!el.checked)a=a.filter(x=>x!==v);setDraft(id,a)}render();return}
 if(el.matches('[data-classify]')){const id=el.dataset.classify,q=questionById[id],d=toArray(draft(q)).slice();d[Number(el.dataset.item)]=Number(el.value);setDraft(id,d);render();return}
 if(el.matches('[data-check]')){checklistSet(Number(el.dataset.check),'done',el.checked);return}
});
root.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-text]'))setDraft(el.dataset.text,el.value);if(el.matches('[data-reason]'))state.notes[el.dataset.reason]=el.value;if(el.matches('[data-slider]')){const n=Number(el.value);state.diagram[el.dataset.slider]=n;const p=el.closest('.diagram-card');if(p&&el.dataset.slider==='contract'){const label=p.querySelector('.slider-label strong'),response=p.querySelector('.contract-bubble.right strong'),result=p.querySelector('.result-chip');if(label)label.textContent=`${n} €`;if(response)response.textContent=`${n} €`;if(result){const ok=n===350;result.classList.toggle('good',ok);result.classList.toggle('warn',!ok);result.textContent=ok?'✓ Preis stimmt überein – Annahme möglich.':'! Preis weicht ab – grundsätzlich neuer Antrag (§ 150 Abs. 2 BGB).'}}}
 if(el.matches('#glossary-search')){state.glossarySearch=el.value;const point=el.selectionStart;render();let f=document.getElementById('glossary-search');f?.focus();try{f?.setSelectionRange(point,point)}catch{}}
});
root.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.id==='auth-form')await authSubmit(form);if(form.id==='password-form'){const data=Object.fromEntries(new FormData(form));try{await syncAction('change-password',data);form.reset();note('Ihr Passwort wurde geändert.')}catch(e){note(e.message,true)}}});
let dragInfo=null;
root.addEventListener('dragstart',e=>{const el=e.target.closest('[data-drag],[data-orderdrag]');if(!el)return;dragInfo=el.dataset.drag?{type:'classify',qid:el.dataset.drag,item:Number(el.dataset.item)}:{type:'order',qid:el.dataset.orderdrag,pos:Number(el.dataset.pos)};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain','rechtsklar')});
root.addEventListener('dragover',e=>{if(e.target.closest('[data-drop],[data-orderdrag]'))e.preventDefault()});
root.addEventListener('drop',e=>{
 setTaskAnchor(e.target);const dest=e.target.closest('[data-drop],[data-orderdrag]');if(!dest||!dragInfo)return;e.preventDefault();if(dragInfo.type==='classify'&&dest.dataset.drop===dragInfo.qid){const q=questionById[dragInfo.qid],d=toArray(draft(q)).slice();d[dragInfo.item]=Number(dest.dataset.category);setDraft(q.id,d);render()}if(dragInfo.type==='order'&&dest.dataset.orderdrag===dragInfo.qid){const q=questionById[dragInfo.qid],d=toArray(draft(q)).slice(),at=Number(dest.dataset.pos),[v]=d.splice(dragInfo.pos,1);d.splice(at,0,v);setDraft(q.id,d);render()}dragInfo=null});
root.addEventListener('dragend',()=>dragInfo=null);
async function initial(){render();try{const me=await api('session',undefined,'GET');state.account=me.user;state.progress=me.progress;render()}catch{}}
initial();
